document:
query TaxCountriesList {
  taxCountryConfigurations {
    ...TaxCountryConfiguration
  }
}

fragment TaxCountryConfiguration on TaxCountryConfiguration {
  country {
    ...CountryWithCode
  }
  taxClassCountryRates {
    rate
    taxClass {
      id
      name
    }
  }
}

fragment CountryWithCode on CountryDisplay {
  country
  code
}
